    if($job>0&&!jobproEmployerJob($employerCompanyId,$job)) { http_response_code(404);jobproEmployerEmpty('Opportunity not found.','Choose an opportunity posted by your company.','/pages/applicants.php','All applicants'); }
    else {
    $list=jobproEmployerApplicants($employerCompanyId,$query,$status,$job,$sort,$page);
?>
<form class="jp-employer-toolbar" action="/pages/applicants.php" method="get" role="search" aria-label="Filter applicants"><div class="jp-employer-search-field"><label for="applicant-query">Search applicants</label><input class="jp-input" id="applicant-query" name="q" maxlength="100" type="search" value="<?= jobproEscape($query) ?>" placeholder="Candidate, email or role"></div><div><label for="applicant-job">Opportunity</label><select class="jp-input" id="applicant-job" name="job"><option value="">All your opportunities</option><?php foreach($jobOptions as$option): ?><option value="<?= (int)$option['id'] ?>"<?= $job===(int)$option['id']?' selected':'' ?>><?= jobproEscape($option['job_title']) ?></option><?php endforeach; ?></select></div><div><label for="applicant-status">Status</label><select class="jp-input" id="applicant-status" name="status"><option value="">All statuses</option><?php foreach(jobproApplicationStatuses()as$value=>$label): ?><option value="<?= $value ?>"<?= $status===$value?' selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></div><div><label for="applicant-sort">Sort by</label><select class="jp-input" id="applicant-sort" name="sort"><?php foreach(['newest'=>'Newest first','oldest'=>'Oldest first','name'=>'Name A–Z']as$value=>$label): ?><option value="<?= $value ?>"<?= $sort===$value?' selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></div><button class="jp-button jp-button--outline" type="submit">Apply filters</button></form>
<div class="jp-employer-results"><p role="status"><?= $list['total'] ?> <?= $list['total']===1?'application':'applications' ?><?= $query!==''?' matching “'.jobproEscape($query).'”':'' ?></p><a class="jp-text-link" href="/pages/applicants.php">Clear filters</a></div>
<?php if(!$list['rows']): jobproEmployerEmpty('No applications to show.','Try different filters, or check back after candidates apply to your open roles.','/pages/jobs.php','Manage your opportunities');else: ?>
<div class="jp-employer-applicant-grid"><?php foreach($list['rows']as$app): ?><article class="jp-employer-applicant-card"><div class="jp-employer-card-top"><span class="jp-employer-initial" aria-hidden="true"><?= jobproEscape(mb_strtoupper(mb_substr($app['candidate_name'],0,1))) ?></span><?php jobproEmployerBadge($app['status']); ?></div><h2><a href="/pages/applicant.php?id=<?= (int)$app['id'] ?>"><?= jobproEscape($app['candidate_name']) ?></a></h2><p class="jp-employer-card-role"><?= jobproEscape($app['qualification']?:'Qualifications not provided') ?></p><p class="jp-employer-muted"><?= jobproEscape(implode(', ',array_filter([$app['location'],$app['country']]))) ?></p><div class="jp-employer-card-job"><small>APPLIED FOR</small><strong><?= jobproEscape($app['job_title']) ?></strong><span><?= jobproEmployerDate($app['applied_at']) ?></span></div><a class="jp-text-link" href="/pages/applicant.php?id=<?= (int)$app['id'] ?>">Review application →</a></article><?php endforeach; ?></div>
<?php jobproEmployerPager($list,'/pages/applicants.php',['q'=>$query,'status'=>$status,'job'=>$job,'sort'=>$sort]);endif;
    }
